<!--
  Example: Responsive tabs — horizontal on mobile, vertical (left) on desktop.
  Copy-paste this as a starting point. Adjust classes and breakpoints as needed.

  Usage in Astro:
    <TabsExample client:load />

  The key concept: placement classes (tablist-top, tablist-left, tablist-right)
  control both the CSS layout AND keyboard navigation automatically.
  Use responsive prefixes to change placement at breakpoints.
-->
<script>
  import Tab from './Tab.svelte'
  import Tablist from './Tablist.svelte'
  import Tabpanel from './Tabpanel.svelte'
  import Tabpanels from './Tabpanels.svelte'
</script>

<div class="tabs-example" style="display: grid; gap: 1rem;">
  <!--
    Mobile: tablist-top (horizontal tabs)
    Desktop (≥1000px): tablist-left (vertical tabs on the left)

    Replace "max-bp10:" and "bp10:" with your own responsive prefixes,
    or use standard Tailwind breakpoints like "max-md:" and "md:".

    If you don't use responsive utility prefixes, use media queries in your CSS:
      @media (max-width: 999px)  { .my-tablist { --placement: top; } }
      @media (min-width: 1000px) { .my-tablist { --placement: left; } }
  -->
  <Tablist
    class="tablist-top"
    target="example-panels"
  >
    <Tab active>First Tab</Tab>
    <Tab>Second Tab</Tab>
    <Tab>Third Tab</Tab>
  </Tablist>

  <Tabpanels id="example-panels">
    <Tabpanel active>
      <p>Content for the first tab.</p>
    </Tabpanel>
    <Tabpanel>
      <p>Content for the second tab.</p>
    </Tabpanel>
    <Tabpanel>
      <p>Content for the third tab.</p>
    </Tabpanel>
  </Tabpanels>
</div>

<style>
  /*
    For responsive placement, add media queries that change the placement class.
    The CSS placement classes (tablist-top, tablist-left, tablist-right) each set
    a --placement CSS custom property that JS reads for keyboard navigation.

    Example with custom breakpoint:
    @media (min-width: 1000px) {
      :global(.tablist) {
        This would need tablist-left class applied at this breakpoint.
        If using Tailwind/utility CSS, apply via responsive prefix in the class attribute.
      }
    }
  */
</style>
